UPDATE dbo.WorkoutSessions SET SplitDayId=NULL
WHERE SplitDayId IN (SELECT SplitDayId FROM dbo.SplitDays WHERE SplitId IN (SELECT SplitId FROM #RemovedWorkoutSplits));
