DECLARE @ImportedSplitId UNIQUEIDENTIFIER;
DECLARE @ImportedDayId UNIQUEIDENTIFIER;
DECLARE @ImportedExerciseId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedSplitId = SplitId FROM dbo.WorkoutSplits
WHERE SourceUrl = N'https://www.muscleandstrength.com/workouts/phul-workout' OR (SourceUrl IS NULL AND Name = N'P.H.U.L. (Power Hypertrophy Upper Lower)');
IF @ImportedSplitId IS NULL
BEGIN
    SET @ImportedSplitId = NEWID();
    INSERT INTO dbo.WorkoutSplits
        (SplitId, Name, Category, Level, DurationDays, Description, HeroImageUrl, IsSystemDefault, SortOrder, RecommendedGoal, Visibility, SourceUrl, SourceAuthor, FullDescription, PopularityRank, PopularityWindow, DaysPerWeek, ProgramDurationWeeks, MinSessionMinutes, MaxSessionMinutes, EquipmentRequired, TargetGender, WorkoutTypeLabel, SourceCategoriesJson, CatalogRank)
    VALUES (@ImportedSplitId, N'P.H.U.L. (Power Hypertrophy Upper Lower)', N'PHUL', N'Intermediate', 4, N'A 12-week 4-day power and hypertrophy upper/lower program for intermediate lifters focused on building muscle. Sessions take about 45-60 minutes. Equipment: barbell, dumbbells, machines.', NULL, 1, 1001, N'BuildMuscle', N'Public', N'https://www.muscleandstrength.com/workouts/phul-workout', NULL, NULL, 4, N'most downloaded in the past 24 hours', 4, 12, 45, 60, N'Barbell, Dumbbells, Machines', N'Male & Female', N'Split', N'["Muscle Building","Men"]', 1);
END
ELSE
BEGIN
    UPDATE dbo.WorkoutSplits SET
        Name=N'P.H.U.L. (Power Hypertrophy Upper Lower)', Category=N'PHUL', Level=N'Intermediate', DurationDays=4,
        Description=N'A 12-week 4-day power and hypertrophy upper/lower program for intermediate lifters focused on building muscle. Sessions take about 45-60 minutes. Equipment: barbell, dumbbells, machines.', HeroImageUrl=NULL, IsSystemDefault=1, SortOrder=1001,
        RecommendedGoal=N'BuildMuscle', Visibility=N'Public', SourceUrl=N'https://www.muscleandstrength.com/workouts/phul-workout',
        SourceAuthor=NULL, FullDescription=NULL, PopularityRank=4, PopularityWindow=N'most downloaded in the past 24 hours',
        DaysPerWeek=4, ProgramDurationWeeks=12, MinSessionMinutes=45, MaxSessionMinutes=60, EquipmentRequired=N'Barbell, Dumbbells, Machines', TargetGender=N'Male & Female', WorkoutTypeLabel=N'Split', SourceCategoriesJson=N'["Muscle Building","Men"]', CatalogRank=1
    WHERE SplitId=@ImportedSplitId;
END
SET @ImportedDayId=NULL;
SELECT @ImportedDayId=SplitDayId FROM dbo.SplitDays WHERE SplitId=@ImportedSplitId AND DayIndex=1;
IF @ImportedDayId IS NULL
BEGIN
    SET @ImportedDayId=NEWID();
    INSERT INTO dbo.SplitDays (SplitDayId, SplitId, DayIndex, Title, FocusLabel, EstimatedMinutes, IsRestDay, SourceNotes)
    VALUES (@ImportedDayId, @ImportedSplitId, 1, N'Day 1 - Upper Power', N'Split', 52, 0, NULL);
END
ELSE UPDATE dbo.SplitDays SET
    Title=N'Day 1 - Upper Power', FocusLabel=N'Split', EstimatedMinutes=52, IsRestDay=0, SourceNotes=NULL
    WHERE SplitDayId=@ImportedDayId;
DELETE FROM dbo.SplitDayExercises WHERE SplitDayId=@ImportedDayId;
SET @ImportedExerciseId=(SELECT TOP (1) ExerciseId FROM dbo.Exercises WHERE Name=N'Barbell Bench Press');
    INSERT INTO dbo.SplitDayExercises (SplitDayId, ExerciseId, SortOrder, TargetSets, TargetRepsLow, TargetRepsHigh, SourceSets, SourceReps)
    VALUES (@ImportedDayId, @ImportedExerciseId, 1, 3, 3, 5, N'3-4', N'3-5');
SET @ImportedExerciseId=(SELECT TOP (1) ExerciseId FROM dbo.Exercises WHERE Name=N'Incline Dumbbell Bench Press');
    INSERT INTO dbo.SplitDayExercises (SplitDayId, ExerciseId, SortOrder, TargetSets, TargetRepsLow, TargetRepsHigh, SourceSets, SourceReps)
